#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8
#define INVALID_INPUT_MSG "INVALID_INPUT\n"
#define CYCLE_MSG "CYCLE\n"

int main(int argc, char *argv[])
{
    // Input validation: need at least one argument (edge) and even number of args
    if (argc < 2) {
        fputs(INVALID_INPUT_MSG, stdout);
        return 1;
    }
    if ((argc - 1) % 2 != 0) {
        fputs(INVALID_INPUT_MSG, stdout);
        return 1;
    }

    int adj[MAXV][MAXV] = {0};
    int indeg[MAXV] = {0};
    bool done[MAXV] = {0};

    // Build graph, increment indegree for each edge (duplicates count)
    for (int i = 1; i < argc; i += 2) {
        char *endptr;
        long u = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0') { fputs(INVALID_INPUT_MSG, stdout); return 1; }
        long v = strtol(argv[i+1], &endptr, 10);
        if (*endptr != '\0') { fputs(INVALID_INPUT_MSG, stdout); return 1; }
        if (u < 0 || u >= MAXV || v < 0 || v >= MAXV) {
            fputs(INVALID_INPUT_MSG, stdout);
            return 1;
        }
        adj[u][v] = 1;          // set edge (duplicates overwrite)
        indeg[v]++;             // indegree counts every occurrence
    }

    int order[MAXV];
    int out_cnt = 0;
    while (out_cnt < MAXV) {
        int v = -1;
        for (int i = 0; i < MAXV; ++i) {
            if (!done[i] && indeg[i] == 0) { v = i; break; }
        }
        if (v == -1) {
            fputs(CYCLE_MSG, stdout);
            return 1;
        }
        order[out_cnt++] = v;
        done[v] = true;
        for (int w = 0; w < MAXV; ++w) {
            if (adj[v][w]) indeg[w]--;
        }
    }

    for (int i = 0; i < out_cnt; ++i) {
        printf("%d", order[i]);
        if (i + 1 < out_cnt) putchar(' ');
    }
    putchar('\n');
    return 0;
}
